function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is between 1 and nums.length.';
  if (nums.some(v => !Number.isInteger(v) || v < -10000 || v > 10000)) return 'Each value is an integer from -10^4 to 10^4.';
  return null;
}

