function findMaxAverage(nums, k) {
  let answer = -Infinity;
  for (let start = 0; start + k <= nums.length; start++) {
    const slice = nums.slice(start, start + k);
    const mean = slice.reduce((acc, v) => acc + v, 0) / k;
    if (mean > answer) answer = mean;
  }
  return answer;
}

