function generate(rand, size) {
  if (size === 'large') {
    const n = 1500 + Math.floor(rand() * 501);
    const k = 1 + Math.floor(rand() * n);
    const nums = Array.from({ length: n }, () => Math.floor(rand() * 20001) - 10000);
    return [nums, k];
  }
  const n = 1 + Math.floor(rand() * 10);
  const k = 1 + Math.floor(rand() * n);
  const span = rand() < 0.2 ? 10000 : 10;
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span);
  return [nums, k];
}
